import re


def chars(text, chars, repl=""):
    """
    Removes all chars in repl from text.
    """
    chars = chars.replace("\\", "\\\\")
    return re.sub(rf"[{chars}]", repl, text)


_UNIXBADCHARS = ("\0", "/", "\\")
_MACBADCHARS = _UNIXBADCHARS + (":",)
_WINBADCHARS = _MACBADCHARS + ("<", ">", '"', "|", "?", "*")
_WINBADWORDS = (
    "com1",
    "com2",
    "com3",
    "com4",
    "com5",
    "com6",
    "com7",
    "com8",
    "com9",
    "lpt1",
